def subtract(a, b):
    # Filter out empty intervals
    a = [iv for iv in a if iv[0] < iv[1]]
    b = [iv for iv in b if iv[0] < iv[1]]

    if not a:
        return []

    # Collect all breakpoints
    points = set()
    for s, e in a:
        points.add(s)
        points.add(e)
    for s, e in b:
        points.add(s)
        points.add(e)

    points = sorted(points)

    result = []
    cur_start = None
    cur_end = None

    for i in range(len(points) - 1):
        p1, p2 = points[i], points[i+1]
        if p1 >= p2:
            continue

        covered_a = any(s <= p1 and e >= p2 for s, e in a)
        covered_b = any(s <= p1 and e >= p2 for s, e in b)

        if covered_a and not covered_b:
            if cur_start is not None and cur_end == p1:
                cur_end = p2
            else:
                if cur_start is not None:
                    result.append([cur_start, cur_end])
                cur_start = p1
                cur_end = p2
        else:
            if cur_start is not None:
                result.append([cur_start, cur_end])
                cur_start = None
                cur_end = None

    if cur_start is not None:
        result.append([cur_start, cur_end])

    return result

